package com.codearena.problem;
import com.codearena.common.api.ApiResponse; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.lang.NonNull; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/problems") public class ProblemController { final ProblemRepository repo; final TagRepository tags; ProblemController(ProblemRepository r,TagRepository t){repo=r;tags=t;} record Card(UUID id,String title,String slug,String description,String difficulty,int timeLimitMs,int memoryLimitMb,int maximumScore,Set<String> supportedLanguages,Set<String> tags){static Card from(Problem p){return new Card(p.id,p.title,p.slug,p.description,p.difficulty,p.timeLimitMs,p.memoryLimitMb,p.maximumScore,p.supportedLanguages,p.tags.stream().map(t->t.name).collect(java.util.stream.Collectors.toSet()));}} @GetMapping ApiResponse<List<Card>> all(){return ApiResponse.of(repo.findByPublishedTrue().stream().map(Card::from).toList());} @GetMapping("/{id}") ApiResponse<Card> one(@PathVariable @NonNull UUID id){return ApiResponse.of(Card.from(repo.findById(id).filter(p->p.published).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND))));} record Create(@NotBlank @Size(max=200) String title,@NotBlank String description,
String difficulty,@NotEmpty Set<String> supportedLanguages,Set<String> tags,Integer timeLimitMs,Integer memoryLimitMb,String inputFormat,String outputFormat,String constraints,Integer maximumScore){} @PostMapping @PreAuthorize("hasAnyRole('TEACHER','ADMIN','SUPER_ADMIN')") @ResponseStatus(HttpStatus.CREATED) ApiResponse<Card> create(@AuthenticationPrincipal String uid,@RequestBody @jakarta.validation.Valid Create c){var p=new Problem();p.authorId=UUID.fromString(uid);p.title=c.title;p.slug=slug(c.title);p.description=c.description;p.inputFormat=c.inputFormat==null?"":c.inputFormat;p.outputFormat=c.outputFormat==null?"":c.outputFormat;p.constraints=c.constraints==null?"":c.constraints;p.difficulty=c.difficulty==null?"EASY":c.difficulty.toUpperCase(Locale.ROOT);if(!Set.of("EASY","MEDIUM","HARD").contains(p.difficulty))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid difficulty");p.supportedLanguages=c.supportedLanguages;p.tags=new HashSet<>();if(c.tags!=null)for(String label:c.tags){var name=label.trim();if(!name.isEmpty()){var tag=tags.findByNameIgnoreCase(name).orElseGet(()->{var t=new Tag();t.name=name;t.slug=name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-");return tags.save(t);});p.tags.add(tag);}}if(c.timeLimitMs!=null)p.timeLimitMs=c.timeLimitMs;if(c.memoryLimitMb!=null)p.memoryLimitMb=c.memoryLimitMb;if(c.maximumScore!=null)p.maximumScore=c.maximumScore;if(p.timeLimitMs<100||p.timeLimitMs>60000||p.memoryLimitMb<16||p.memoryLimitMb>4096||p.maximumScore<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Problem limits are outside allowed ranges");return ApiResponse.of(Card.from(repo.save(p)));}
private String slug(String title){var base=title.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");return base+"-"+UUID.randomUUID().toString().substring(0,8);}
}
